import { Component, OnDestroy, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { LoadingController } from '@ionic/angular';
import { Subscription } from 'rxjs';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { Urls } from 'src/app/core/common/Urls';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SliderService } from 'src/app/data/service/site/Slider.service';

export interface SparkPlugGapInput {
  factoryGap: number;
  compression: number;
  boost: number;
  coilKv: number;
  supplyVolts: number;
}

export interface SparkPlugGapResult {
  gapMm: number;
  lowMm: number;
  highMm: number;
  gapInches: number;
  pressureReductionMm: number;
  electricalAdjustmentMm: number;
}

const clamp = (value: number, low: number, high: number): number => Math.min(high, Math.max(low, value));

// A bounded tuning heuristic, not a prediction of breakdown voltage or cylinder pressure.
// Higher boost/compression narrow the OEM gap; electrical inputs make only small corrections.
export function calculateSparkPlugGap(input: SparkPlugGapInput): SparkPlugGapResult {
  const pressureReductionMm = clamp(
    Math.max(0, input.compression - 10) * 0.025 + input.boost * 0.14,
    0, 0.35
  );
  const coilAdjustmentMm = clamp((input.coilKv - 35) * 0.003, -0.06, 0.04);
  const supplyAdjustmentMm = clamp((input.supplyVolts - 13.8) * 0.025, -0.06, 0.02);
  const electricalAdjustmentMm = coilAdjustmentMm + supplyAdjustmentMm;
  const gapMm = clamp(input.factoryGap - pressureReductionMm + electricalAdjustmentMm,
    0.45, Math.min(1.55, input.factoryGap + 0.06));

  return {
    gapMm,
    lowMm: Math.max(0.45, gapMm - 0.05),
    highMm: Math.min(1.55, gapMm + 0.05),
    gapInches: gapMm / 25.4,
    pressureReductionMm,
    electricalAdjustmentMm
  };
}

@Component({
  selector: 'app-spark-plug-gap',
  templateUrl: './spark-plug-gap.component.html',
  styleUrls: ['./spark-plug-gap.component.scss']
})
export class SparkPlugGapComponent implements OnInit, OnDestroy {
  readonly defaults: SparkPlugGapInput = {
    factoryGap: 0.8, compression: 9.5, boost: 0, coilKv: 35, supplyVolts: 13.8
  };
  readonly fields = [
    { key: 'factoryGap', label: 'گپ استاندارد سازنده', unit: 'mm', min: 0.5, max: 1.5, step: 0.01,
      help: 'گپ توصیه‌شده برای همین موتور و همین شمع؛ مبنای محاسبه است.' },
    { key: 'compression', label: 'نسبت تراکم استاتیک', unit: ':1', min: 6, max: 16, step: 0.1,
      help: 'نسبت تراکم موتور؛ فشار واقعی سیلندر به تایمینگ میل‌سوپاپ هم وابسته است.' },
    { key: 'boost', label: 'فشار بوست گیج', unit: 'bar', min: 0, max: 3, step: 0.05,
      help: 'بیشترین بوست زیر بار، نسبت به فشار محیط؛ برای تنفس طبیعی صفر وارد کنید.' },
    { key: 'coilKv', label: 'ولتاژ اسمی خروجی کویل', unit: 'kV', min: 20, max: 60, step: 1,
      help: 'عدد نامی ولتاژ ثانویه از مشخصات کویل؛ ولتاژ واقعی جرقه زیر بار نیست.' },
    { key: 'supplyVolts', label: 'ولتاژ تغذیه زیر بار', unit: 'V', min: 10, max: 15.5, step: 0.1,
      help: 'ولتاژ اندازه‌گیری‌شده در تغذیه کویل/سیستم جرقه هنگام کار موتور.' }
  ];

  form: FormGroup;
  result: SparkPlugGapResult | null = null;
  isCheck = true;
  isShow = false;
  private readonly subscriptions = new Subscription();

  constructor(
    private fb: FormBuilder,
    private router: Router,
    public loadingController: LoadingController,
    private courseService: CourseService,
    private siteService: SliderService
  ) {}

  ngOnInit(): void {
    const controls = {};
    this.fields.forEach(field => {
      controls[field.key] = [this.defaults[field.key],
        [Validators.required, Validators.min(field.min), Validators.max(field.max)]];
    });
    this.form = this.fb.group(controls);
    this.subscriptions.add(this.form.valueChanges.subscribe(() => this.calculate()));
    this.calculate();
    void this.check();
  }

  ngOnDestroy(): void { this.subscriptions.unsubscribe(); }

  async check(): Promise<void> {
    await SharedIonic.loading(this.loadingController);
    try {
      const tool = await this.siteService.GetTunerPlusById(50).toPromise();
      if (tool.status !== GResponse.SuccessStatus || !tool.data || !tool.data.isActive) {
        throw new Error('Tool unavailable');
      }
      if (!tool.data.isFree) {
        const courses = await this.courseService.GetUserCoursesId().toPromise();
        const ownsCourse = courses.status === GResponse.SuccessStatus &&
          Array.isArray(courses.data) &&
          (tool.data.courseIds || []).some(id => courses.data.some(owned => +owned === +id));
        if (!ownsCourse) { throw new Error('Course access denied'); }
        const access = await this.courseService.GetUserTunerPlusAccess().toPromise();
        if (access.status !== GResponse.SuccessStatus) { throw new Error('Tuner Plus access denied'); }
      }
      this.isCheck = false;
      this.isShow = true;
    } catch {
      this.isCheck = true;
      this.isShow = false;
      await this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
    } finally {
      await SharedIonic.dismissLoading(this.loadingController);
    }
  }

  calculate(): void {
    if (!this.form || this.form.invalid) {
      this.result = null;
      return;
    }
    this.result = calculateSparkPlugGap(this.form.value as SparkPlugGapInput);
  }

  reset(): void { this.form.reset(this.defaults); }
}
